const START_FLOOR = 1;

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for markReachableFloors(graph, floor, visited):
//     when this call returns, `floor` and every floor reachable
//     from it by ladders is in the visited set.
const markReachableFloors = (graph, floor, visited) => {
    // Base case
    if (visited.has(floor)) return;

    // Process node
    visited.add(floor);

    // Recurse on neighbors
    const floorInGraph = graph.hasOwnProperty(floor);
    if (!floorInGraph) return;

    const neighbors = graph[floor];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and every
        // floor reachable from it is in the visited set. Trust it, do
        // not trace it. This function already put `floor` into visited,
        // and each neighbor's contract covers the rest — together, that
        // is this function's full contract, kept.
        markReachableFloors(graph, neighbor, visited);
    }
};

const highestFloor = (ladders) => {
    // Floor numbers go up to a billion, so the graph must be keyed by
    // floor number (a plain object) instead of using an array slot per floor.
    const graph = buildGraph(ladders);

    const visited = new Set();
    // The recursive leap of faith: trust the contract. When this
    // call returns, visited holds floor 1 and every floor reachable
    // from it by ladders. We do not trace inside; we just scan
    // visited for the highest floor.
    markReachableFloors(graph, START_FLOOR, visited);

    let highestReachableFloor = START_FLOOR;

    for (const floor of visited) {
        if (floor <= highestReachableFloor) continue;

        highestReachableFloor = floor;
    }

    return highestReachableFloor;
};

const INTERNET_HOUSE = 1;

const buildGraph = (edges) => {
    const graph = {};

    for (const edge of edges) {
        const [nodeOne, nodeTwo] = edge;

        const nodeOneInGraph = graph.hasOwnProperty(nodeOne);
        const nodeTwoInGraph = graph.hasOwnProperty(nodeTwo);

        if (!nodeOneInGraph) graph[nodeOne] = [];
        if (!nodeTwoInGraph) graph[nodeTwo] = [];

        graph[nodeOne].push(nodeTwo);
        graph[nodeTwo].push(nodeOne);
    }

    return graph;
};

// CONTRACT for markOnlineHouses(graph, house, visited):
//     when this call returns, `house` and every house connected
//     to it by cables is in the visited set.
const markOnlineHouses = (graph, house, visited) => {
    // Base case
    if (visited.has(house)) return;

    // Process node
    visited.add(house);

    // Recurse on neighbors
    const houseInGraph = graph.hasOwnProperty(house);
    if (!houseInGraph) return;

    const neighbors = graph[house];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `neighbor` and every
        // house connected to it is in the visited set. Trust it, do
        // not trace it. This function already put `house` into visited,
        // and each neighbor's contract covers the rest — together, that
        // is this function's full contract, kept.
        markOnlineHouses(graph, neighbor, visited);
    }
};

const findOfflineHouses = (n, cables) => {
    const graph = buildGraph(cables);

    // Every house the DFS reaches from house 1 is online.
    const visited = new Set();
    // The recursive leap of faith: trust the contract. When this
    // call returns, visited holds house 1 and every house connected
    // to it — all the online houses. We do not trace inside; we just
    // report the houses that are missing from visited.
    markOnlineHouses(graph, INTERNET_HOUSE, visited);

    const offlineHouses = [];

    // Checking houses from 1 up to n means the answer comes out already sorted.
    for (let house = 1; house <= n; house++) {
        if (visited.has(house)) continue;

        offlineHouses.push(house);
    }

    return offlineHouses;
};

const DECIMAL_CELL = '1';
const DECIMAL_ANSWER = 'decimal';
const BINARY_ANSWER = 'binary';
const NEITHER_ANSWER = 'neither';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

// CONTRACT for labelRegion(grid, row, col, regionCellType, regionLabel, visited, regionLabels):
//     when this call returns, every cell of the region containing
//     (`row`, `col`) — the connected cells whose character equals
//     `regionCellType` — is in the visited set and has
//     `regionLabel` stored for it in `regionLabels`.
const labelRegion = (grid, row, col, regionCellType, regionLabel, visited, regionLabels) => {
    // Base cases
    if (!isInBounds(grid, row, col)) return;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return;

    // A region only contains cells with the SAME character as its start.
    if (grid[row][col] !== regionCellType) return;

    // Process node
    visited.add(curPositionString);
    regionLabels.set(curPositionString, regionLabel);

    // Recurse on neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, the neighbor's side of
        // the region is in the visited set and labeled. Trust it, do
        // not trace it. This function already put (`row`, `col`) into
        // visited and labeled it, and each neighbor's contract covers
        // the rest — together, that is this function's full contract,
        // kept.
        labelRegion(grid, newRow, newCol, regionCellType, regionLabel, visited, regionLabels);
    }
};

const whoCanTravel = (grid, queries) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    // Label every region once up front. Two cells are connected exactly
    // when they share a label, so each query becomes a cheap lookup
    // instead of its own DFS.
    const visited = new Set();
    const regionLabels = new Map();
    let nextRegionLabel = 0;

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);
            if (visited.has(curPositionString)) continue;

            // The recursive leap of faith: trust the contract. When this
            // call returns, the whole region around this cell is in the
            // visited set and every one of its cells shares the same label.
            // We do not trace inside; we just move on to the next unlabeled
            // cell.
            labelRegion(grid, row, col, grid[row][col], nextRegionLabel, visited, regionLabels);
            nextRegionLabel++;
        }
    }

    const answers = [];

    for (const query of queries) {
        const [startRow, startCol, targetRow, targetCol] = query;

        const startLabel = regionLabels.get(getPositionString(startRow, startCol));
        const targetLabel = regionLabels.get(getPositionString(targetRow, targetCol));

        // Different labels mean different regions (or different cell types).
        if (startLabel !== targetLabel) {
            answers.push(NEITHER_ANSWER);
            continue;
        }

        const cellType = grid[startRow][startCol];
        answers.push(cellType === DECIMAL_CELL ? DECIMAL_ANSWER : BINARY_ANSWER);
    }

    return answers;
};
